  "content": "<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Account settings</title>
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link
      rel="stylesheet"
      href="https://fonts.googleapis.com/css2?family=Lora:ital,wght@0,400..700;1,400..700&family=Source+Sans+3:wght@300..900&family=JetBrains+Mono:wght@400;500;600&display=swap"
    />
    <link rel="stylesheet" href="node_modules/@taproot-ds/tokens/dist/css/tokens.css" />
    <link rel="stylesheet" href="node_modules/@taproot-ds/tokens/dist/css/base.css" />
    <script type="module" src="node_modules/@taproot-ds/web-components/src/index.js"></script>
    <style>
      main {
        max-width: 40rem;
        margin: 0 auto;
        padding: var(--ds-primitives-space-10) var(--ds-primitives-space-4);
        display: flex;
        flex-direction: column;
        gap: var(--ds-primitives-space-8);
      }
      h1,
      h2,
      p {
        margin: 0;
      }
      section {
        display: flex;
        flex-direction: column;
        gap: var(--ds-primitives-space-4);
        padding: var(--ds-primitives-space-6);
        background: var(--ds-semantic-color-background-surface);
        border: var(--ds-semantic-border-width) solid var(--ds-semantic-color-border-default);
        border-radius: var(--ds-semantic-radius-surface);
      }
      section.danger-zone {
        border-color: var(--ds-semantic-color-border-status-danger-default);
      }
      form {
        display: flex;
        flex-direction: column;
        gap: var(--ds-primitives-space-4);
      }
      .actions {
        display: flex;
        flex-wrap: wrap;
        justify-content: flex-end;
        gap: var(--ds-primitives-space-2);
      }
      .muted {
        color: var(--ds-semantic-color-foreground-muted);
      }
      .danger-zone .actions {
        justify-content: flex-start;
      }
    </style>
  </head>
  <body>
    <main>
      <h1>Account settings</h1>

      <section aria-labelledby="profile-heading">
        <h2 id="profile-heading">Profile</h2>
        <form id="profile-form" novalidate>
          <ds-text-field
            label="Display name"
            name="displayName"
            value="Alex Rivera"
            autocomplete="name"
            hint="Shown to other people on your posts and comments."
            required
          ></ds-text-field>
          <ds-text-field
            label="Email address"
            name="email"
            type="email"
            value="alex@example.com"
            autocomplete="email"
            hint="Used for sign-in and account notices."
            required
          ></ds-text-field>
          <div class="actions">
            <ds-button id="cancel-button" type="button" variant="secondary">Cancel</ds-button>
            <ds-button type="submit" variant="primary">Save changes</ds-button>
          </div>
          <p id="profile-status" class="muted" role="status"></p>
        </form>
      </section>

      <section class="danger-zone" aria-labelledby="danger-heading">
        <h2 id="danger-heading">Delete account</h2>
        <p>
          Deleting your account permanently removes your profile and all of your data. This cannot
          be undone.
        </p>
        <div class="actions">
          <ds-button id="delete-button" type="button" variant="destructive">Delete account</ds-button>
        </div>
        <p id="delete-status" class="muted" role="status"></p>
      </section>
    </main>

    <ds-dialog
      id="delete-dialog"
      label="Delete your account?"
      description="This permanently deletes your account and cannot be undone."
    >
      <p>Your profile, settings, and all of your data will be removed. You will be signed out.</p>
      <ds-button id="delete-cancel" slot="actions" variant="secondary">Keep account</ds-button>
      <ds-button id="delete-confirm" slot="actions" variant="destructive">Delete account</ds-button>
    </ds-dialog>

    <script type="module">
      const form = document.getElementById("profile-form");
      const nameField = form.querySelector('[name="displayName"]');
      const emailField = form.querySelector('[name="email"]');
      const profileStatus = document.getElementById("profile-status");
      const emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

      for (const field of [nameField, emailField]) {
        field.addEventListener("input", () => {
          field.removeAttribute("error");
          profileStatus.textContent = "";
        });
      }

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        const name = (nameField.value ?? "").trim();
        const email = (emailField.value ?? "").trim();
        let firstInvalid = null;

        if (!name) {
          nameField.setAttribute("error", "Enter a display name.");
          firstInvalid ??= nameField;
        }
        if (!email) {
          emailField.setAttribute("error", "Enter an email address.");
          firstInvalid ??= emailField;
        } else if (!emailPattern.test(email)) {
          emailField.setAttribute("error", "Enter an email address like name@example.com.");
          firstInvalid ??= emailField;
        }

        if (firstInvalid) {
          profileStatus.textContent = "";
          firstInvalid.focus();
          return;
        }

        // Saved values become the new initial values that Cancel restores.
        nameField.setAttribute("value", name);
        emailField.setAttribute("value", email);
        profileStatus.textContent = "Your changes have been saved.";
      });

      document.getElementById("cancel-button").addEventListener("click", () => {
        form.reset();
        nameField.removeAttribute("error");
        emailField.removeAttribute("error");
        profileStatus.textContent = "Changes discarded.";
      });

      const dialog = document.getElementById("delete-dialog");
      document.getElementById("delete-button").addEventListener("click", () => dialog.showModal());
      document.getElementById("delete-cancel").addEventListener("click", () => dialog.close());
      document.getElementById("delete-confirm").addEventListener("click", () => {
        dialog.close();
        document.getElementById("delete-button").setAttribute("disabled", "");
        document.getElementById("delete-status").textContent =
          "Your account has been deleted.";
      });
    </script>
  </body>
</html>
